from collections import deque,Counter
R=C=30
lab=[[-1]*C for _ in range(R)]; comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c] and lab[r][c]<0:
   q=[(r,c)]; lab[r][c]=len(comps); pts=[]
   while q:
    a,b=q.pop(); pts.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     x,y=a+da,b+db
     if 0<=x<R and 0<=y<C and grid[x][y] and lab[x][y]<0: lab[x][y]=lab[r][c];q.append((x,y))
   comps.append(pts)
print([(i,len(p),[(r,c,grid[r][c]) for r,c in p if grid[r][c]>1],(min(r for r,c in p),max(r for r,c in p),min(c for r,c in p),max(c for r,c in p))) for i,p in enumerate(comps)])

out=[row[:] for row in grid]
seedcolors={i:next(grid[r][c] for r,c in pts if grid[r][c]>1) for i,pts in enumerate(comps) if any(grid[r][c]>1 for r,c in pts)}
centers=[]
for r in range(1,29):
 for c in range(1,29):
  vals=[lab[x][y] for x in range(r-1,r+2) for y in range(c-1,c+2)]
  if vals[0]>=0 and len(set(vals))==1:
   comp=vals[0]
   if comp in seedcolors:
    centers.append((r,c,seedcolors[comp]))
    out[r][c]=seedcolors[comp]
print('n',len(centers), centers)
print('\n'.join(' '.join(map(str,row)) for row in out))
